/* Kierunek na podstawie referencji: ludzie, fotografia i czytelne oferty. */
themes.people={name:'Ludzie i praca',tag:'NOWA PROPOZYCJA / LUDZIE I PRACA',title:'Więcej życia. Więcej konkretów.',desc:'Fotografia ludzi przy pracy, mocne otwarcie i czytelne karty ofert. Białe tło, czerwień i czerń; dotychczasowe kierunki pozostają do porównania.',colors:['#FFFFFF','#D92932','#151515','#F6F6F6'],labels:['Biel / główne tło','Czerwień / marka i akcje','Czerń / tekst','Szarość / tło sekcji'],heading:'DM Sans',body:'DM Sans',brand:'Dobra praca zaczyna się od ludzi.',rationale:'Fotografie pokazują prawdziwy kontekst pracy. Wyraźna typografia i proste karty ofert ułatwiają porównanie warunków. Marka zachowuje jasny charakter: kolor służy do zaznaczania istotnych treści, nie wypełnia całego ekranu.',geometry:'Zaokrąglenia 20 px na kartach, większe przy zdjęciu otwierającym. Trzy kolumny ofert na komputerze, jedna na telefonie. Wynagrodzenie i lokalizacja zawsze w tym samym miejscu.',voice:'Prosto i konkretnie. Opowiadamy o zawodzie, miejscu i warunkach. Nie obiecujemy idealnej pracy ani gwarantowanego zatrudnienia.'};
jobs.push({id:5,title:'Pracownik magazynu',company:'Dockside Belgium',city:'Gandawa',salary:'16–19 €',period:'brutto / godz.',category:'Logistyka',initials:'DB',tags:['Kompletowanie zamówień','Pełny etat'],desc:'Przyjmowanie dostaw, kompletowanie zamówień i przygotowywanie przesyłek w magazynie.'},{id:6,title:'Technik utrzymania ruchu',company:'Atelier Works',city:'Bruksela',salary:'23–27 €',period:'brutto / godz.',category:'Technika',initials:'AW',tags:['Diagnostyka maszyn','Umowa o pracę'],desc:'Diagnostyka, przeglądy i konserwacja urządzeń produkcyjnych w zespole technicznym.'});
const pi=(name)=>{const paths={pin:'<path d="M18 10c0 5-6 10-6 10S6 15 6 10a6 6 0 1 1 12 0Z"/><circle cx="12" cy="10" r="2"/>',clock:'<circle cx="12" cy="12" r="8"/><path d="M12 7v5l3 2"/>',money:'<circle cx="12" cy="12" r="8"/><path d="M15 8c-5-3-8 8 0 8M7 10h7M7 13h6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',bookmark:'<path d="M7 4h10v16l-5-3-5 3Z"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]}</svg>`;};
function peopleCard(j){return `<article class="p-job"><div class="p-card-heading"><span class="p-company">${j.company}</span><button class="p-save" data-save="${j.id}" aria-pressed="${saved.has(j.id)}" aria-label="Zapisz ofertę: ${j.title}">${saved.has(j.id)?'★':pi('bookmark')}</button></div><h3><a href="#detail-${j.id}" data-detail="${j.id}">${j.title}</a></h3><div class="p-facts"><span>${pi('pin')}${j.city}</span><strong>${pi('money')}${j.salary} <small>${j.period}</small></strong><span class="p-date">${pi('clock')}Oferta demonstracyjna</span></div><div class="p-card-bottom"><div>${j.tags.map(t=>`<span class="p-tag">${t}</span>`).join('')}</div><a class="p-open" href="#detail-${j.id}" data-detail="${j.id}" aria-label="Zobacz ofertę: ${j.title}">${pi('arrow')}</a></div></article>`;}
const oldPeopleHome=home;
home=function(){if(theme!=='people')return oldPeopleHome();return `${nav()}<main><section class="p-hero"><div class="p-hero-copy"><span class="p-eyebrow">PRACA W BELGII</span><h1>Twoje umiejętności.<br>Twoje miejsce.<br><em>Twój nowy start.</em></h1><p>Znajdź pracę, w której wykorzystasz to, co potrafisz. Porównaj warunki i aplikuj swoim profilem — bez pisania CV.</p><div class="p-hero-links">${button('Przeglądaj oferty','jobs')}${button('Zobacz profil kandydata','candidate','text-link')}</div></div><figure class="p-hero-photo"><img src="assets/team.jpg" alt="Współpraca w miejscu pracy" width="1000" height="800"><figcaption><span class="p-caption-icon">.be</span><span><strong>Praca to przede wszystkim ludzie.</strong><small>Znajdź swoje miejsce w Belgii.</small></span></figcaption></figure></section><section class="p-search-section" aria-label="Wyszukiwarka ofert">${search()}</section><section class="p-offers"><div class="section-head"><div><h2>Najnowsze oferty pracy</h2><p>Sprawdź, kogo szukają pracodawcy.</p></div>${button('Zobacz wszystkie oferty →','jobs')}</div><div class="p-job-grid">${jobs.map(peopleCard).join('')}</div></section><section class="p-fields"><div class="section-head"><div><h2>W czym jesteś dobry?</h2><p>Zacznij od swojej branży.</p></div></div><div class="p-sector-grid"><button class="p-sector" data-category="Logistyka"><img src="assets/warehouse.jpg" alt="Miejsce pracy w logistyce" width="700" height="450" loading="lazy"><span><strong>Logistyka i magazyn</strong>${pi('arrow')}</span></button><button class="p-sector" data-category="Technika"><img src="assets/workshop.jpg" alt="Praca techniczna w warsztacie" width="700" height="450" loading="lazy"><span><strong>Technika i produkcja</strong>${pi('arrow')}</span></button><aside class="p-profile-note"><span class="p-eyebrow">PROFIL ZAMIAST CV</span><h2>Nie musisz umieć<br>pisać o sobie.</h2><p>Wystarczy kilka informacji: zawód, doświadczenie i umiejętności. Resztę pokażesz w pracy.</p>${button('Poznaj profil zawodowy','candidate')}</aside></div></section></main>${footer()}<div class="p-photo-credit">Zdjęcia ilustracyjne · <a href="photo-sources.html" target="_blank" rel="noopener">Autorzy fotografii</a></div>`;};
const oldPeopleJobs=jobList;
jobList=function(){if(theme!=='people')return oldPeopleJobs();const list=jobs.filter(j=>(j.title+' '+j.company+' '+j.category).toLowerCase().includes(query.toLowerCase())&&j.city.toLowerCase().includes(city.toLowerCase())&&(!categories.length||categories.includes(j.category)));return `${nav()}<main><header class="p-list-header"><span class="p-eyebrow">OFERTY PRACY</span><h1>Znajdź swoje miejsce w Belgii.</h1>${search()}</header><div class="p-list-layout"><aside class="filters"><h3>Branża</h3>${['Logistyka','Produkcja','Budownictwo','Technika'].map(x=>`<label><input type="checkbox" data-filter="${x}" ${categories.includes(x)?'checked':''}>${x}</label>`).join('')}<h3>Lokalizacja</h3><select id="city-filter" aria-label="Lokalizacja"><option value="">Cała Belgia</option ${city==='Antwerpia'?'selected':''}>Antwerpia</option ${city==='Bruksela'?'selected':''}>Bruksela</option ${city==='Gandawa'?'selected':''}>Gandawa</option></select><button class="text-link" id="reset">Wyczyść filtry</button></aside><section><div class="results-top"><strong>Liczba ofert: ${list.length}</strong><span>Dane demonstracyjne</span></div><div class="p-job-grid">${list.map(peopleCard).join('')}</div>${list.length?'':'<div class="empty"><h2>Nie ma ofert dla tych filtrów.</h2><p>Zmień stanowisko lub lokalizację.</p></div>'}</section></div></main>${footer()}`;};
const oldPeopleBrand=brand;
brand=function(){if(theme!=='people')return oldPeopleBrand();return `${nav()}<main class="p-brand"><div class="p-brand-head"><div><span class="p-eyebrow">KIERUNEK MARKI</span><h1>Dobra praca zaczyna się od ludzi.</h1><p>Fotografia i wyraźna typografia nadają charakter. Czytelne karty ofert pomagają podjąć decyzję. Biel pozostaje głównym tłem.</p></div><img src="assets/team.jpg" width="600" height="450" alt="Ludzie współpracujący w miejscu pracy"></div><div class="palette-list">${themes.people.colors.map((c,i)=>`<div class="color-item"><div class="color-box" style="background:${c}"></div><strong>${themes.people.labels[i]}</strong><span>${c}</span></div>`).join('')}</div><div class="brand-grid"><article><span class="p-eyebrow">TYPOGRAFIA</span><div class="specimen">Aa 012<br>ąęłńó</div><h2>DM Sans</h2><p>Wyraźne nagłówki, naturalne proporcje liter. Opisy 16–18 px. Dane o ofercie mają własne, stałe miejsce.</p></article><article><span class="p-eyebrow">FOTOGRAFIA</span><h2>Prawdziwy kontekst.</h2><p>Praca w warsztacie, zespół w magazynie, rozmowa przy zadaniu. Naturalne światło i autentyczne sytuacje, bez uścisków dłoni przed obiektywem.</p></article><article><span class="p-eyebrow">KARTY OFERT</span><h2>Porównaj bez szukania.</h2><p>Stanowisko, firma, lokalizacja, wynagrodzenie i umiejętności. Spójna kolejność, duży tytuł i wyraźne przejście do szczegółów.</p></article></div><div class="p-brand-logo">${logo()}<span>Biel. Czerwień. Czerń.</span></div></main>${footer()}`;};
const peopleInitial=requestedConceptHash.slice(1).split('/');theme='people';view=peopleInitial[0]==='people'&&['home','jobs','candidate','employer','brand'].includes(peopleInitial[1])?peopleInitial[1]:'home';document.title='Pracuj.be — Ludzie i praca';render();
